def fl(addr):
    off=addr-0x3000
    return struct.unpack('<f', b[0x3000+off:0x3000+off+4])[0]
funcs=[]
for l in asm:
    m=re.match(r'^([0-9a-f]+) <([^>]+)>:', l)
    if m: funcs.append((int(m.group(1),16),m.group(2)))
for i,(a,n) in enumerate(funcs):
    end=funcs[i+1][0] if i+1<len(funcs) else 0x2c30
    print('\n###',n,hex(a),hex(end))
    for l in asm:
        m=re.match(r'\s*([0-9a-f]+):\s+.*#\s*([0-9a-f]+) <',l)
        if not m: continue
        ad=int(m.group(1),16)
        if a <= ad < end:
            tgt=int(m.group(2),16)
            if tgt in funcs:
                pass
            if 0x312c <= tgt < 0x31b0:
                print(l.strip(), '=> float', fl(tgt))
